		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🏷分类",null,1,1)
	arList=[,["全部","category"],["韓漫","category/list/2"],["出版漫畫","category/list/4"],["3D漫畫","category/list/1"],["單本","category/list/3"],["其它類","category/list/5"]]
	arList.map([title,uri]=>{
		tag=java.t2s(title);
		url=`{{getUrl()}}${uri}/page/{{page}}`;
		push(tag, url, 1, 0.25);
		});
		xrList=[,["全🌸部",""],["韓🌸漫","/list/2"],["出版🌸漫畫","/list/4"],["3D🌸漫畫","/list/1"],["單🌸本","/list/3"],["🌸其它類","/list/5"]]
		nrList=[["全部",""],["连载","/finish/1"],["完结","finish/2"]]
		mrList=[["更新時間","category/order/addtime"],["熱門人氣","category/order/hits"],["最高評分","category/order/score"],["最多收藏","category/order/shits"],["新漫入庫","category/order/id"],["今日人氣","category/order/rhits"]]
	xrList.map([title,ure]=>{
		tsg=java.t2s(title);
		push(tsg,`{{getUrl()}}category${ure}/page/{{page}}`,1,1);
		nrList.map([tag,uri]=>{
url=`{{getUrl()}}category${ure}${uri}/page/{{page}}`
push(tag,url,1,0.25);
});
mrList.map([teg,uro]=>{
nrList.map([tag,uri]=>{
	tog=java.t2s(teg);
	url=`{{getUrl()}}${uro}${ure}/page/{{page}}`;
push(tog,url,1,0.25);
});
});
});
