ruleContent.nextContentUrl:
@js:
try{
data=java.getString("h1@text");
//java.log(data)
ys=data.match(/\d+\/(\d+).?$/)||[];
page=ys[1];
var next=[];
if(data&&page){
	for(i=2;i<=page;i++){
		url=baseUrl.replace(/.html/,
			`_${i}.html`);
		next.push(url);
		}
		next;
	}
}catch(e){
	java.log(e)
	}finally{next}

ruleToc.chapterList:
@js:
var v=source.getVariable(),
ax=u=>java.ajax(u);
bu=book.bookUrl;
bv=(v==1&&!/_\d+/.test(baseUrl));
java.setContent(bv?ax(bu):src);
c="#list dl dd:gt(9) a||ul[class=p2] li a";
p=`//div[@id="list"]/dl/dd[position()>9]/a||//ul[@class="p2"]/li/a`;
var cs=java.getElement(c),
path=p=>java.getElements(p);
cs!=""?cs:path(p)

